  return member;
}

export async function revokeInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertCan(actor, "member:invite", orgResource(actor.orgId));
  return invitationRepo.revokeInvitation(actor.orgId, invitationId);
}

/**
 * Re-issuing does not mint a new row: the original is revoked and replaced so
 * the audit trail keeps both, and the old link stops working immediately.
 */
export async function resendInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertOrgScope(actor, actor.orgId);
  assertCan(actor, "member:invite", orgResource(actor.orgId));

  const previous = requireFound(
    await invitationRepo.findInvitationById(actor.orgId, invitationId),
    "Invitation",
    invitationId,
  );

  if (previous.acceptedAt !== null || previous.revokedAt !== null) {
    throw new Error("Only an unaccepted invitation can be re-sent");
  }
  const org = requireFound(await orgRepo.findOrgById(actor.orgId), "Organization", actor.orgId);
  const used = (await memberRepo.countActiveMembers(actor.orgId)) +
    (await invitationRepo.countPendingInvitations(actor.orgId));
  const renewsHeldSeat = previous.expiresAt > toIsoTimestamp(new Date());
  if (wouldExceedLimit(org.plan, "seats", used, renewsHeldSeat ? 0 : 1)) {
    const limits = getPlanLimits(org.plan);
    throw new Error(`Plan ${org.plan} includes ${limits.seats} seats and ${used} are taken`);
  }
  await invitationRepo.revokeInvitation(actor.orgId, invitationId);
  const token = randomToken(32);
  const invitation = await invitationRepo.insertInvitation(
    actor.orgId,
    { orgId: actor.orgId, email: previous.email, role: previous.role, expiresInDays: DEFAULT_EXPIRY_DAYS },
    actor.userId,
    hashToken(token),
  );
  await emit("member.invited", {
    orgId: actor.orgId,
    actorId: actor.userId,
    occurredAt: invitation.createdAt,
    email: invitation.email,
    role: invitation.role,
  });
  return invitation;
}
